import { randomBytes, randomUUID, createHash, timingSafeEqual } from 'node:crypto';
import type { IncomingMessage, ServerResponse } from 'node:http';
import type { DbDriver } from '../../db/driver.js';
import { WorkspaceError } from './types.js';

const hash = (value: string) => createHash('sha256').update(value).digest();

/** Bootstrap material is generated by the owner-only Unix socket, never by HTTP. */
export class WorkspaceAuth {
  private tickets = new Map<
    string,
    { ownerId: string; expires: number; codeExpires: number; origin: string; code: string }
  >();
  private attempts: number[] = [];
  constructor(
    public port: number,
    private db: DbDriver,
  ) {}

  private tailnetOrigin: string | null = null;

  configureTailnet(origin: string | null): void {
    const old = this.tailnetOrigin;
    this.tailnetOrigin = origin;
    if (old && old !== origin) {
      for (const [key, value] of this.tickets) if (value.origin === old) this.tickets.delete(key);
    }
  }

  private requestOrigin(req?: IncomingMessage): string {
    const host = req?.headers.host ?? `localhost:${this.port}`;
    if ([`localhost:${this.port}`, `127.0.0.1:${this.port}`].includes(host)) return `http://${host}`;
    if (
      this.tailnetOrigin &&
      new URL(this.tailnetOrigin).host === host &&
      ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(req?.socket.remoteAddress ?? '')
    )
      return this.tailnetOrigin;
    throw new WorkspaceError(403, 'Invalid workspace host.');
  }

  issue(ownerId: string, origin = `http://localhost:${this.port}`): string {
    if (origin !== `http://localhost:${this.port}` && origin !== this.tailnetOrigin)
      throw new WorkspaceError(403, 'This workspace address is not enabled.');
    this.prune();
    const token = randomBytes(32).toString('base64url');
    this.tickets.set(hash(token).toString('hex'), {
      ownerId,
      expires: Date.now() + 120_000,
      codeExpires: Date.now() + 600_000,
      origin,
      code: randomBytes(6).toString('hex').toUpperCase(),
    });
    return `${origin}/#pair=${token}`;
  }

  codeFor(url: string): string | undefined {
    const token = new URLSearchParams(new URL(url).hash.slice(1)).get('pair') ?? '';
    return this.tickets.get(hash(token).toString('hex'))?.code.match(/.{4}/g)?.join('-');
  }

  async pair(token: string, res: ServerResponse, req?: IncomingMessage) {
    this.attempts = this.attempts.filter((at) => at > Date.now() - 60_000);
    if (this.attempts.length >= 10) throw new WorkspaceError(429, 'Too many pairing attempts. Wait a minute.');
    let key = hash(token).toString('hex');
    const usingCode = !this.tickets.has(key);
    if (usingCode) {
      const code = token.replace(/[-\s]/g, '').toUpperCase();
      key = [...this.tickets].find(([, ticket]) => ticket.code === code)?.[0] ?? key;
    }
    const ticket = this.tickets.get(key);
    if (!ticket || (usingCode ? ticket.codeExpires : ticket.expires) < Date.now()) {
      this.attempts.push(Date.now());
      throw new WorkspaceError(
        401,
        usingCode
          ? 'This code expired or was already used. Create a new code in Settings → Access on your workspace host. Codes last 10 minutes.'
          : 'This link expired or was already used. Create another in Settings → Access on your workspace host.',
      );
    }
    if (ticket.origin !== this.requestOrigin(req)) {
      this.attempts.push(Date.now());
      throw new WorkspaceError(
        401,
        'This code or link belongs to a different workspace address. For your iPhone, create a device code in Settings → Access, or run ncl workspace open --tailnet.',
      );
    }
    this.tickets.delete(key);
    return this.createDevice(ticket.ownerId, ticket.origin, res);
  }

  private async createDevice(
    ownerId: string,
    origin: string,
    res: ServerResponse,
    installationId?: string,
    name?: string,
  ) {
    const token = randomBytes(32).toString('base64url');
    const deviceId = randomUUID();
    const now = new Date().toISOString();
    await this.db.run(
      'INSERT INTO ws_devices (id,owner_id,token_hash,origin,name,installation_id,created_at,last_seen) VALUES (?,?,?,?,?,?,?,?)',
      deviceId,
      ownerId,
      hash(token).toString('hex'),
      origin,
      name ?? 'Paired browser',
      installationId ?? null,
      now,
      now,
    );
    this.cookie(res, token, origin);
    return { ownerId, deviceId, csrf: hash(token + ':csrf').toString('hex'), origin };
  }

  private cookieName(origin: string) {
    const url=new URL(origin);
    return `${url.protocol==='https:'?'nc_workspace_tailnet':'nc_workspace'}_${url.port||(url.protocol==='https:'?'443':'80')}`;
  }

  private cookie(res: ServerResponse, token: string, origin: string) {
    res.setHeader(
      'Set-Cookie',
      `${this.cookieName(origin)}=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=31536000${origin.startsWith('https:') ? '; Secure' : ''}`,
    );
  }

  async identify(req: IncomingMessage, res: ServerResponse, installationId: string, name: string) {
    const principal = await this.authorize(req, true);
    const row = await this.db.get<{ installation_id: string | null }>(
      'SELECT installation_id FROM ws_devices WHERE id=?',
      principal.deviceId,
    );
    if (row?.installation_id && row.installation_id !== installationId)
      return this.createDevice(principal.ownerId, principal.origin, res, installationId, name);
    await this.db.run(
      'UPDATE ws_devices SET name=CASE WHEN installation_id IS NULL THEN ? ELSE name END, installation_id=? WHERE id=?',
      name,
      installationId,
      principal.deviceId,
    );
    return principal;
  }

  checkHost(req: IncomingMessage): void {
    this.requestOrigin(req);
  }

  checkOrigin(req: IncomingMessage): void {
    const expected = this.requestOrigin(req);
    const origin = req.headers.origin;
    if (origin && origin !== expected) throw new WorkspaceError(403, 'Cross-origin workspace access is blocked.');
    if (
      req.headers['sec-fetch-site'] === 'cross-site' &&
      !(
        req.method === 'GET' &&
        req.headers['sec-fetch-mode'] === 'navigate' &&
        req.headers['sec-fetch-dest'] === 'document'
      )
    )
      throw new WorkspaceError(403, 'Cross-site workspace access is blocked.');
  }

  async authorize(req: IncomingMessage, mutation = false, res?: ServerResponse) {
    this.checkOrigin(req);
    const origin = this.requestOrigin(req);
    const names=[this.cookieName(origin),origin.startsWith('https:')?'nc_workspace_tailnet':'nc_workspace'];
    const cookies=(req.headers.cookie??'').split(';').map(value=>value.trim());
    // Prefer the scoped token; legacy credentials are accepted only when no
    // scoped cookie exists, then renewed under the new name after validation.
    const cookie=names.map(name=>cookies.find(value=>value.startsWith(`${name}=`))).find(Boolean);
    const token=cookie?.slice(cookie.indexOf('=')+1);
    const device = token
      ? await this.db.get<{ id: string; owner_id: string; origin: string; last_seen: string }>(
          'SELECT id,owner_id,origin,last_seen FROM ws_devices WHERE token_hash=? AND revoked_at IS NULL',
          hash(token).toString('hex'),
        )
      : undefined;
    if (!device || device.origin !== origin)
      throw new WorkspaceError(401, 'Pair this browser using Settings → Access on your workspace host, or ncl workspace open.');
    const csrf = hash(token + ':csrf').toString('hex');
    if (res) this.cookie(res, token!, origin);
    if (mutation) {
      const received = req.headers['x-workspace-csrf'];
      if (typeof received !== 'string' || !timingSafeEqual(hash(received), hash(csrf)))
        throw new WorkspaceError(403, 'Invalid workspace request. Reload and try again.');
    }
    if (Date.now() - Date.parse(device.last_seen) > 60_000)
      await this.db.run('UPDATE ws_devices SET last_seen=? WHERE id=?', new Date().toISOString(), device.id);
    return { ownerId: device.owner_id, deviceId: device.id, csrf, origin };
  }

  private prune(): void {
    for (const [key, value] of this.tickets) if (value.codeExpires < Date.now()) this.tickets.delete(key);
  }
}
